## Grapheme clusters, against the test cases of the Rust crate upstream uses
## (tests/data/grapheme_clusters.txt, generated by tools/graphemes_tables.py).
import std/[os, sequtils, strutils, unicode, unittest]
import ../src/gleam_in_nim/graphemes

proc decode(codePoints: string): string =
  for codePoint in strutils.splitWhitespace(codePoints): result.add Rune(parseHexInt(codePoint)).toUTF8

suite "graphemes":
  test "the tables are those of Unicode 17":
    check unicodeVersion == (17, 0, 0)

  test "every test case of unicode-segmentation splits as it does there":
    var cases, failures = 0
    for line in lines(currentSourcePath.parentDir / "data" / "grapheme_clusters.txt"):
      if line.startsWith("#") or line.len == 0: continue
      inc cases
      let expected = line.split(" / ").map(decode)
      let text = expected.join
      if toSeq(graphemes(text)) != expected or graphemesCount(text) != expected.len:
        inc failures
        checkpoint "wrong split for: " & line
    check cases == 766
    check failures == 0

  test "the cases upstream's crate adds to the official ones":
    # Two Prepend characters between two other characters.
    check toSeq(graphemes(" ؀؀ ")) == @[" ", "؀؀ "]
    # A Prepend character followed by two others.
    check toSeq(graphemes("؀  ")) == @["؀ ", " "]

  test "everyday strings":
    check graphemesCount("") == 0
    check graphemesCount("wibble") == 6
    check graphemesCount("è") == 1
    check graphemesCount("é") == 1
    check graphemesCount("\r\n") == 1
    check graphemesCount("🇮🇹🇬🇧") == 2
    check graphemesCount("👩‍👩‍👧‍👦") == 1
    check graphemesCount("क्षि") == 1
